int mca_lex(void *yylval_param, void *yylloc_param)
{
    if (g_current_token == NULL) {
        return 0; // End of input
    }
    /* Line-join law (U363 gap 1): a trailing `@attr...` run may continue on
     * its own lines. The EL rule emits MC_ENDL for every line break
     * unconditionally (comment lines included), so an own-line `@` had no
     * production arm and the row died E2083. The join lives here — the
     * parser's token fetcher, not the lexer — so the parser sees the same
     * stream the same-line spelling produces while `mcc fmt`, which walks
     * the raw token list through `mcc_lex`, keeps the author's layout. */
    if (g_current_token->tid == MC_ENDL) {
        mc_lex_token *run = g_current_token;
        while (run->tid == MC_ENDL && run->next != NULL) {
            run = (mc_lex_token*)run->next;
        }
        if (run->tid == MCPT_AT) {
            g_current_token = run;
        }
    }
    mc_lex_token *token = g_current_token;
    mc_lex_token **yylval = (mc_lex_token**)yylval_param;
    *yylval = token;
    // Byte-offset span of this token, carried to the parser through the
    // location fields (columns hold byte offsets, lines stay 1). YYLLOC_DEFAULT
    // chains these into @1..@N, so every reduction sees the full rule span,
    // including tokens the action discards. The location type is the
    // api.prefix-renamed MCA_LTYPE from mca.tab.h.
    MCA_LTYPE *yloc = (MCA_LTYPE*)yylloc_param;
    if (yloc != NULL) {
        yloc->first_line = 1;
        yloc->first_column = (int)token->tpos;
        yloc->last_line = 1;
        yloc->last_column = (int)(token->tpos + token->tlen);
    }
    mprintf(MCC_LOG_TOKEN, "[%d|%s|%d..%d] ", token->tid, token->tstring, token->tpos, token->tpos+token->tlen);
    g_current_token = (mc_lex_token*)token->next;
    g_last_token = token;

    return token->tid;
}
